CREATE TYPE "Role" AS ENUM ('CUSTOMER','ADMIN');
CREATE TYPE "TokenPurpose" AS ENUM ('VERIFY_EMAIL','RESET_PASSWORD');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"mobile" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"emailVerifiedAt" TIMESTAMP(3),"termsAcceptedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuthToken" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"purpose" "TokenPurpose" NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Address" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"recipient" TEXT NOT NULL,"line1" TEXT NOT NULL,"city" TEXT NOT NULL,"state" TEXT NOT NULL,"postalCode" TEXT NOT NULL,"country" TEXT NOT NULL DEFAULT 'IN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE INDEX "AuthToken_userId_purpose_idx" ON "AuthToken"("userId","purpose");
CREATE INDEX "AuthToken_expiresAt_idx" ON "AuthToken"("expiresAt");
CREATE INDEX "Address_userId_idx" ON "Address"("userId");
